element.style.display = 'none'
if (!document.getElementById('comments-prominent')) {
  var container = document.createElement('div');
  container.id = 'comments-prominent';
  container.innerHTML = '<h2 style="margin: 1em 0; font-size: 1.5em;">💬 Community Discussion</h2>';
  container.appendChild(element.cloneNode(true));
  var pageHeader = document.querySelector('.page-header');
  if (pageHeader) {
    pageHeader.parentNode.insertBefore(container, pageHeader.nextSibling);
  }
}

if (element.parentNode) {
  element.style.fontSize = '1.2em';
  element.style.padding = '8px 16px';
  element.style.borderRadius = '8px';
  element.style.backgroundColor = '#FA005A';
  element.style.color = '#fff';
  element.style.fontWeight = 'bold';
  element.style.display = 'inline-flex';
  element.style.alignItems = 'center';
  element.style.gap = '6px';
  element.style.transition = 'background-color 0.2s, transform 0.1s';
  element.style.textDecoration = 'none';
  var label = document.createElement('span');
  label.textContent = 'Discuss';
  if (!element.querySelector('span')) {
    element.appendChild(label);
  }
}

if (element.parentNode) {
  element.style.fontSize = '1.2em';
  element.style.fontWeight = 'bold';
  element.style.color = '#FA005A';
  element.style.padding = '6px 12px';
  element.style.borderRadius = '6px';
  element.style.backgroundColor = '#fff0f5';
  element.style.border = '2px solid #FA005A';
}
